19	void ConfigManipulation::apply(DynamicPrintConfig* config, DynamicPrintConfig* new_config)
20	{
21	    bool modified = false;
22	    m_applying_keys = config->diff(*new_config);
23	    for (auto opt_key : m_applying_keys) {
24	        config->set_key_value(opt_key, new_config->option(opt_key)->clone());
25	        modified = true;
26	    }
27	    if (modified && load_config != nullptr)
28	        load_config();
29	    m_applying_keys.clear();
30	}
