57	void ConfigManipulation::check_nozzle_recommended_temperature_range(DynamicPrintConfig *config) {
58	    if (is_msg_dlg_already_exist)
59	        return;
60	
61	    int temperature_range_low, temperature_range_high;
62	    if (!get_temperature_range(config, temperature_range_low, temperature_range_high)) return;
63	
64	    // Get the selected filament type
65	    std::string filament_type = "";
66	    if (config->has("filament_type") && config->option<ConfigOptionStrings>("filament_type")->values.size() > 0) {
67	        filament_type = config->option<ConfigOptionStrings>("filament_type")->values[0];
68	    }
69	
70	    int min_recommended_temp = 190;
71	    int max_recommended_temp = 300;
72	
73	    if (!MaterialType::get_temperature_range(filament_type, min_recommended_temp, max_recommended_temp)){
74	        filament_type = "Unknown";
75	    }
76	
77	    wxString msg_text;
78	    bool     need_check = false;
79	    if (temperature_range_low < min_recommended_temp) {
80	        msg_text += wxString::Format(_L("A minimum temperature above %d\u2103 is recommended for %s.\n"),
81	                                        min_recommended_temp, filament_type);
82	        need_check = true;
83	    }
84	    if (temperature_range_high > max_recommended_temp) {
85	        msg_text += wxString::Format(_L("A maximum temperature below %d\u2103 is recommended for %s.\n"),
86	                                        max_recommended_temp, filament_type);
87	        need_check = true;
88	    }
89	    if (temperature_range_low > temperature_range_high) {
90	        msg_text += _L("The recommended minimum temperature cannot be higher than the recommended maximum temperature.\n");
91	        need_check = true;
92	    }
93	    if (need_check) {
94	        msg_text += _L("Please check.\n");
95	        MessageDialog dialog(m_msg_dlg_parent, msg_text, "", wxICON_WARNING | wxOK);
96	        is_msg_dlg_already_exist = true;
97	        dialog.ShowModal();
98	        is_msg_dlg_already_exist = false;
99	    }
100	}
