102	void ConfigManipulation::check_nozzle_temperature_range(DynamicPrintConfig *config)
103	{
104	    if (is_msg_dlg_already_exist)
105	        return;
106	
107	    int temperature_range_low, temperature_range_high;
108	    if (!get_temperature_range(config, temperature_range_low, temperature_range_high)) return;
109	
110	    if (config->has("nozzle_temperature")) {
111	        if (config->opt_int("nozzle_temperature", 0) < temperature_range_low || config->opt_int("nozzle_temperature", 0) > temperature_range_high) {
112	            wxString msg_text = _(L("Nozzle may be blocked when the temperature is out of recommended range.\n"
113	                "Please make sure whether to use the temperature to print.\n\n"));
114	            msg_text += wxString::Format(_L("The recommended nozzle temperature for this filament type is [%d, %d] degrees Celsius."), temperature_range_low, temperature_range_high);
115	            MessageDialog dialog(m_msg_dlg_parent, msg_text, "", wxICON_WARNING | wxOK);
116	            is_msg_dlg_already_exist = true;
117	            dialog.ShowModal();
118	            is_msg_dlg_already_exist = false;
119	        }
120	    }
121	}
