167	void ConfigManipulation::check_chamber_temperature(DynamicPrintConfig* config)
168	{
169	   bool support_chamber_temp_control=GUI::wxGetApp().preset_bundle->printers.get_selected_preset().config.opt_bool("support_chamber_temp_control");
170	    if (support_chamber_temp_control&&config->has("chamber_temperature")) {
171	        std::string filament_type = config->option<ConfigOptionStrings>("filament_type")->get_at(0);
172	        int chamber_min_temp, chamber_max_temp;
173	    if (MaterialType::get_chamber_temperature_range(filament_type, chamber_min_temp, chamber_max_temp)) {
174	            if (chamber_max_temp < config->option<ConfigOptionInts>("chamber_temperature")->get_at(0)) {
175	                wxString msg_text = wxString::Format(_L("Current chamber temperature is higher than the material's safe temperature, this may result in material softening and clogging. "
176	                                                        "The maximum safe temperature for the material is %d"), chamber_max_temp);
177	                MessageDialog dialog(m_msg_dlg_parent, msg_text, "", wxICON_WARNING | wxOK);
178	                is_msg_dlg_already_exist = true;
179	                dialog.ShowModal();
180	                is_msg_dlg_already_exist = false;
181	            }
182	        }
183	    }
184	}
