186	void ConfigManipulation::check_chamber_minimal_temperature(DynamicPrintConfig* config)
187	{
188	    // Orca: the minimal chamber temperature is a "start printing" threshold that is passed to the
189	    // print start macro. It must not exceed the target chamber temperature, otherwise the macro
190	    // could wait forever for a temperature the heater is never asked to reach.
191	    if (config->has("chamber_minimal_temperature") && config->has("chamber_temperature")) {
192	        const int chamber_min_temp    = config->option<ConfigOptionInts>("chamber_minimal_temperature")->get_at(0);
193	        const int chamber_target_temp = config->option<ConfigOptionInts>("chamber_temperature")->get_at(0);
194	        if (chamber_min_temp > chamber_target_temp) {
195	            wxString msg_text = wxString::Format(_L("The minimal chamber temperature (%d℃) is higher than the target chamber temperature (%d℃). "
196	                                                    "The minimal value is the threshold at which printing starts while the chamber keeps heating toward the target, "
197	                                                    "so it should not exceed it. It will be clamped to the target."),
198	                                                 chamber_min_temp, chamber_target_temp);
199	            MessageDialog dialog(m_msg_dlg_parent, msg_text, "", wxICON_WARNING | wxOK);
200	            DynamicPrintConfig new_conf = *config;
201	            is_msg_dlg_already_exist    = true;
202	            dialog.ShowModal();
203	            new_conf.set_key_value("chamber_minimal_temperature", new ConfigOptionInts({chamber_target_temp}));
204	            apply(config, &new_conf);
205	            is_msg_dlg_already_exist = false;
206	        }
207	    }
208	}
