210	void ConfigManipulation::update_print_fff_config(DynamicPrintConfig* config, const bool is_global_config, const bool is_plate_config)
211	{
212	    // #ys_FIXME_to_delete
213	    //! Temporary workaround for the correct updates of the TextCtrl (like "layer_height"):
214	    // KillFocus() for the wxSpinCtrl use CallAfter function. So,
215	    // to except the duplicate call of the update() after dialog->ShowModal(),
216	    // let check if this process is already started.
217	    if (is_msg_dlg_already_exist)
218	        return;
219	
220	    bool is_object_config = (!is_global_config && !is_plate_config);
221	
222	    // layer_height shouldn't be equal to zero
223	    auto layer_height = config->opt_float("layer_height");
224	    auto gpreset = GUI::wxGetApp().preset_bundle->printers.get_edited_preset();
225	    if (layer_height < EPSILON)
226	    {
227	        const wxString msg_text = _(L("Too small layer height.\nReset to 0.2."));
228	        MessageDialog dialog(m_msg_dlg_parent, msg_text, "", wxICON_WARNING | wxOK);
229	        DynamicPrintConfig new_conf = *config;
230	        is_msg_dlg_already_exist = true;
231	        dialog.ShowModal();
232	        new_conf.set_key_value("layer_height", new ConfigOptionFloat(0.2));
233	        apply(config, &new_conf);
234	        is_msg_dlg_already_exist = false;
235	    }
236	
237	    //BBS: limite the max layer_herght
238	    auto max_lh = gpreset.config.opt_float("max_layer_height",0);
239	    if (max_lh > 0.2 && layer_height > max_lh+ EPSILON)
240	    {
241	        const wxString msg_text = wxString::Format(L"Too large layer height.\nReset to %0.3f.", max_lh);
242	        MessageDialog dialog(nullptr, msg_text, "", wxICON_WARNING | wxOK);
243	        DynamicPrintConfig new_conf = *config;
244	        is_msg_dlg_already_exist = true;
245	        dialog.ShowModal();
246	        new_conf.set_key_value("layer_height", new ConfigOptionFloat(max_lh));
247	        apply(config, &new_conf);
248	        is_msg_dlg_already_exist = false;
249	    }
250	
251	    //BBS: ironing_spacing shouldn't be too small or equal to zero
252	    if (config->opt_float("ironing_spacing") < 0.05)
253	    {
254	        const wxString msg_text = _(L("Too small ironing spacing.\nReset to 0.1."));
255	        MessageDialog dialog(nullptr, msg_text, "", wxICON_WARNING | wxOK);
256	        DynamicPrintConfig new_conf = *config;
257	        is_msg_dlg_already_exist = true;
258	        dialog.ShowModal();
259	        new_conf.set_key_value("ironing_spacing", new ConfigOptionFloat(0.1));
260	        apply(config, &new_conf);
261	        is_msg_dlg_already_exist = false;
262	    }
263	    if (config->opt_float("support_ironing_spacing") < 0.05)
264	    {
265	        const wxString msg_text = _(L("Too small ironing spacing.\nReset to 0.1."));
266	        MessageDialog dialog(nullptr, msg_text, "", wxICON_WARNING | wxOK);
267	        DynamicPrintConfig new_conf = *config;
268	        is_msg_dlg_already_exist = true;
269	        dialog.ShowModal();
270	        new_conf.set_key_value("support_ironing_spacing", new ConfigOptionFloat(0.1));
271	        apply(config, &new_conf);
272	        is_msg_dlg_already_exist = false;
273	    }
274	
275	    if (config->option<ConfigOptionFloat>("initial_layer_print_height")->value < EPSILON)
276	    {
277	        const wxString msg_text = _(L("Zero initial layer height is invalid.\n\nThe first layer height will be reset to 0.2."));
278	        MessageDialog dialog(m_msg_dlg_parent, msg_text, "", wxICON_WARNING | wxOK);
279	        DynamicPrintConfig new_conf = *config;
280	        is_msg_dlg_already_exist = true;
281	        dialog.ShowModal();
282	        new_conf.set_key_value("initial_layer_print_height", new ConfigOptionFloat(0.2));
283	        apply(config, &new_conf);
284	        is_msg_dlg_already_exist = false;
285	    }
286	
287	    if (abs(config->option<ConfigOptionFloat>("xy_hole_compensation")->value) > 2)
288	    {
289	        const wxString msg_text = _(L("This setting is only used for model size tunning with small value in some cases.\n"
290	                                      "For example, when model size has small error and hard to be assembled.\n"
291	                                      "For large size tuning, please use model scale function.\n\n"
292	                                      "The value will be reset to 0."));
293	        MessageDialog dialog(m_msg_dlg_parent, msg_text, "", wxICON_WARNING | wxOK);
294	        DynamicPrintConfig new_conf = *config;
295	        is_msg_dlg_already_exist = true;
296	        dialog.ShowModal();
297	        new_conf.set_key_value("xy_hole_compensation", new ConfigOptionFloat(0));
298	        apply(config, &new_conf);
299	        is_msg_dlg_already_exist = false;
300	    }
301	
302	    if (abs(config->option<ConfigOptionFloat>("xy_contour_compensation")->value) > 2)
303	    {
304	        const wxString msg_text = _(L("This setting is only used for model size tunning with small value in some cases.\n"
305	                                      "For example, when model size has small error and hard to be assembled.\n"
306	                                      "For large size tuning, please use model scale function.\n\n"
307	                                      "The value will be reset to 0."));
308	        MessageDialog dialog(m_msg_dlg_parent, msg_text, "", wxICON_WARNING | wxOK);
309	        DynamicPrintConfig new_conf = *config;
310	        is_msg_dlg_already_exist = true;
311	        dialog.ShowModal();
312	        new_conf.set_key_value("xy_contour_compensation", new ConfigOptionFloat(0));
313	        apply(config, &new_conf);
314	        is_msg_dlg_already_exist = false;
315	    }
316	
317	    if (config->option<ConfigOptionFloat>("elefant_foot_compensation")->value > 1)
318	    {
319	        const wxString msg_text = _(L("Too large elephant foot compensation is unreasonable.\n"
320	                                      "If really have serious elephant foot effect, please check other settings.\n"
321	                                      "For example, whether bed temperature is too high.\n\n"
322	                                      "The value will be reset to 0."));
323	        MessageDialog dialog(m_msg_dlg_parent, msg_text, "", wxICON_WARNING | wxOK);
324	        DynamicPrintConfig new_conf = *config;
325	        is_msg_dlg_already_exist = true;
326	        dialog.ShowModal();
327	        new_conf.set_key_value("elefant_foot_compensation", new ConfigOptionFloat(0));
328	        apply(config, &new_conf);
329	        is_msg_dlg_already_exist = false;
330	    }
331	
332	    if (config->option<ConfigOptionBool>("enable_wrapping_detection")->value) {
333	        std::string printer_type = wxGetApp().preset_bundle->printers.get_edited_preset().get_printer_type(wxGetApp().preset_bundle);
334	        if (!DevPrinterConfigUtil::support_wrapping_detection(printer_type)) {
335	            DynamicPrintConfig new_conf = *config;
336	            new_conf.set_key_value("enable_wrapping_detection", new ConfigOptionBool(false));
337	            apply(config, &new_conf);
338	        }
339	    }
340	
341	    double sparse_infill_density = config->option<ConfigOptionPercent>("sparse_infill_density")->value;
342	    int    fill_multiline        = config->option<ConfigOptionInt>("fill_multiline")->value;
343	    auto timelapse_type = config->opt_enum<TimelapseType>("timelapse_type");
344	
345	    if (!is_plate_config &&
346	        config->opt_bool("spiral_mode") &&
347	        ! (config->opt_int("wall_loops") == 1 &&
348	           config->opt_int("top_shell_layers") == 0 &&
349	           sparse_infill_density == 0 &&
350	           ! config->opt_bool("enable_support") &&
351	           config->opt_int("enforce_support_layers") == 0 &&
352	           ! config->opt_bool("detect_thin_wall") &&
353	           ! config->opt_bool("overhang_reverse") &&
354	            config->opt_enum<TimelapseType>("timelapse_type") == TimelapseType::tlTraditional &&
355	            !config->opt_bool("enable_wrapping_detection")))
356	    {
357	        DynamicPrintConfig new_conf = *config;
358	        auto answer = show_spiral_mode_settings_dialog(is_object_config);
359	        bool support = true;
360	        if (answer == wxID_YES) {
