570	void ConfigManipulation::apply_null_fff_config(DynamicPrintConfig *config, std::vector<std::string> const &keys, std::map<ObjectBase *, ModelConfig *> const &configs)
571	{
572	    for (auto &k : keys) {
573	        if (k == "independent_support_layer_height" || k == "enable_support" || k == "detect_thin_wall")
574	            config->set_key_value(k, new ConfigOptionBool(true));
575	        else if (k == "wall_loops")
576	            config->set_key_value(k, new ConfigOptionInt(0));
577	        else if (k == "top_shell_layers" || k == "enforce_support_layers")
578	            config->set_key_value(k, new ConfigOptionInt(1));
579	        else if (k == "sparse_infill_density") {
580	            double v = config->option<ConfigOptionPercent>(k)->value;
581	            for (auto &c : configs) {
582	                auto o = c.second->get().option<ConfigOptionPercent>(k);
583	                if (o && o->value > v) v = o->value;
584	            }
585	            config->set_key_value(k, new ConfigOptionPercent(v)); // sparse_infill_pattern
586	        }
587	        else if (k == "detect_overhang_wall")
588	            config->set_key_value(k, new ConfigOptionBool(false));
589	        else if (k == "sparse_infill_pattern")
590	            config->set_key_value(k, new ConfigOptionEnum<InfillPattern>(ipGrid));
591	    }
592	}
