3551	bool Tab::validate_custom_gcode(const wxString& title, const std::string& gcode)
3552	{
3553	    std::vector<std::string> tags;
3554	    bool invalid = GCodeProcessor::contains_reserved_tags(gcode, 5, tags);
3555	    if (invalid) {
3556	        std::string lines = ":\n";
3557	        for (const std::string& keyword : tags)
3558	            lines += ";" + keyword + "\n";
3559	        wxString reports = format_wxstr(
3560	            _L_PLURAL("Following line %s contains reserved keywords.\nPlease remove it, or will beat G-code visualization and printing time estimation.",
3561	                      "Following lines %s contain reserved keywords.\nPlease remove them, or will beat G-code visualization and printing time estimation.",
3562	                      tags.size()),
3563	            lines);
3564	        //wxMessageDialog dialog(wxGetApp().mainframe, reports, _L("Found reserved keywords in") + " " + _(title), wxICON_WARNING | wxOK);
3565	        MessageDialog dialog(wxGetApp().mainframe, reports, _L("Reserved keywords found") + " " + _(title), wxICON_WARNING | wxOK);
3566	        dialog.ShowModal();
3567	    }
3568	    return !invalid;
3569	}
