6276	// If the current preset is dirty, the user is asked whether the changes may be discarded.
6277	// if the current preset was not dirty, or the user agreed to discard the changes, 1 is returned.
6278	bool Tab::may_discard_current_dirty_preset(PresetCollection *presets /*= nullptr*/, const std::string &new_printer_name /*= ""*/, bool no_transfer, bool no_transfer_variant)
6279	{
6280	    if (presets == nullptr) presets = m_presets;
6281	
6282	    UnsavedChangesDialog dlg(m_type, presets, new_printer_name, no_transfer);
6283	    if (dlg.ShowModal() == wxID_CANCEL)
6284	        return false;
6285	
6286	    if (dlg.save_preset())  // save selected changes
6287	    {
6288	        const std::vector<std::string>& unselected_options = dlg.get_unselected_options(presets->type());
6289	        const std::string& name = dlg.get_preset_name();
6290	        //BBS: add project embedded preset relate logic
6291	        bool save_to_project = dlg.get_save_to_project_option();
6292	
6293	        if (m_type == presets->type()) // save changes for the current preset from this tab
6294	        {
6295	            // revert unselected options to the old values
6296	            presets->get_edited_preset().config.apply_only(presets->get_selected_preset().config, unselected_options);
6297	            //BBS: add project embedded preset relate logic
6298	            save_preset(name, false, save_to_project);
6299	            //save_preset(name);
6300	        }
6301	        else
6302	        {
6303	            //BBS: add project embedded preset relate logic
6304	            m_preset_bundle->save_changes_for_preset(name, presets->type(), unselected_options, save_to_project);
6305	            //m_preset_bundle->save_changes_for_preset(name, presets->type(), unselected_options);
6306	
6307	            // If filament preset is saved for multi-material printer preset,
6308	            // there are cases when filament comboboxs are updated for old (non-modified) colors,
6309	            // but in full_config a filament_colors option aren't.
6310	            if (presets->type() == Preset::TYPE_FILAMENT && wxGetApp().extruders_edited_cnt() > 1)
6311	                wxGetApp().plater()->force_filament_colors_update();
6312	        }
6313	    }
6314	    else if (dlg.transfer_changes()) // move selected changes
6315	    {
6316	        std::vector<std::string> selected_options = dlg.get_selected_options();
6317	        if (!no_transfer && no_transfer_variant) {
6318	            auto & options_list = wxGetApp().get_tab(presets->type())->m_options_list;
6319	            bool has_variants = false;
6320	            for (auto &opt : selected_options) {
6321	                if (auto n = opt.find('#'); n != std::string::npos) {
6322	                    auto iter = options_list.lower_bound(opt.substr(0, n));
6323	                    if (iter == options_list.end() || opt.compare(0, n, iter->first)) {
6324	                        has_variants = true;
6325	                        opt.clear();
6326	                    }
6327	                }
6328	            }
6329	            if (has_variants) {
6330	                auto msg = _L("Switching to a printer with different extruder types or numbers will discard or reset changes to extruder or multi-nozzle-related parameters.");
6331	                MessageDialog(wxGetApp().plater(), msg, _L("Use Modified Value"), wxOK | wxICON_WARNING).ShowModal();
6332	                selected_options.erase(std::remove(selected_options.begin(), selected_options.end(), ""), selected_options.end());
6333	            }
6334	        }
6335	
6336	        if (m_type == presets->type()) // move changes for the current preset from this tab
6337	        {
6338	            if (m_type == Preset::TYPE_PRINTER) {
6339	                auto it = std::find(selected_options.begin(), selected_options.end(), "extruders_count");
6340	                if (it != selected_options.end()) {
6341	                    // erase "extruders_count" option from the list
6342	                    selected_options.erase(it);
6343	                    // cache the extruders count
6344	                    static_cast<TabPrinter*>(this)->cache_extruder_cnt();
6345	                }
6346	            }
6347	
6348	            // copy selected options to the cache from edited preset
6349	            cache_config_diff(selected_options);
6350	        }
6351	        else
6352	            wxGetApp().get_tab(presets->type())->cache_config_diff(selected_options);
6353	    }
6354	
6355	    return true;
6356	}
