7234	// ORCA: Session-only suppression keys for temperature-pair safety warnings.
7235	static std::unordered_set<std::string> s_filament_temp_pair_warning_suppressed_for_session;
7236	
7237	// ORCA: Validate that first-layer and other-layer temperature pairs are within safety limits, and warn the user if not.
7238	bool Tab::validate_filament_temperature_pairs()
7239	{
7240	    if (m_type != Preset::TYPE_FILAMENT || m_presets == nullptr)
7241	        return true;
7242	
7243	    // Warn only for newly edited state, not for unchanged presets.
7244	    if (!m_presets->current_is_dirty())
7245	        return true;
7246	
7247	    Preset& edited_preset = m_presets->get_edited_preset();
7248	    DynamicPrintConfig& config = edited_preset.config;
7249	    const std::string suppress_key = edited_preset.name;
7250	    // User opted out for this preset during current app session.
7251	    if (!suppress_key.empty() && s_filament_temp_pair_warning_suppressed_for_session.count(suppress_key) > 0)
7252	        return true;
7253	
7254	    struct TempPairRule
7255	    {
7256	        wxString    label;
7257	        std::string first_layer_key;
7258	        std::string other_layer_key;
7259	        int         max_delta;
7260	    };
7261	
7262	    std::vector<TempPairRule> temp_pair_rules;
7263	    temp_pair_rules.push_back({_L("Nozzle"), "nozzle_temperature_initial_layer", "nozzle_temperature", 30});
7264	
7265	    // Derive bed labels/keys from curr_bed_type metadata (BedType order excludes btDefault).
7266	    if (const ConfigOptionDef* bed_type_def = print_config_def.get("curr_bed_type");
7267	        bed_type_def != nullptr) {
7268	        for (int bt = static_cast<int>(btPC); bt < static_cast<int>(btCount); ++bt) {
7269	            const BedType     bed_type  = static_cast<BedType>(bt);
7270	            const size_t      label_idx = static_cast<size_t>(bt - static_cast<int>(btPC));
7271	            const std::string first_key = get_bed_temp_1st_layer_key(bed_type);
7272	            const std::string other_key = get_bed_temp_key(bed_type);
7273	            if (first_key.empty() || other_key.empty())
7274	                continue;
7275	
7276	            wxString label = _(bed_type_def->enum_labels[label_idx]);
7277	            temp_pair_rules.push_back({label, first_key, other_key, 15});
7278	        }
7279	    }
7280	
7281	    wxString invalid_pairs;
7282	    int      invalid_count = 0;
7283	
7284	    for (const TempPairRule& rule : temp_pair_rules) {
7285	        if (!config.has(rule.first_layer_key) || !config.has(rule.other_layer_key))
7286	            continue;
7287	
7288	        const ConfigOptionInts* first_opt = config.option<ConfigOptionInts>(rule.first_layer_key);
7289	        const ConfigOptionInts* other_opt = config.option<ConfigOptionInts>(rule.other_layer_key);
7290	        if (first_opt == nullptr || other_opt == nullptr || first_opt->values.empty() || other_opt->values.empty())
7291	            continue;
7292	
7293	        const int first_temp = first_opt->get_at(0);
7294	        const int other_temp = other_opt->get_at(0);
7295	
7296	        // Keep existing semantics: 0 means unsupported/off for these temperatures.
7297	        if (first_temp <= 0 || other_temp <= 0)
7298	            continue;
7299	
7300	        const int delta = std::abs(first_temp - other_temp);
7301	        if (delta <= rule.max_delta)
7302	            continue;
7303	
7304	        const wxString deg_c   = wxString::FromUTF8("°C");
7305	        const wxString bullet  = wxString::FromUTF8("•");
7306	        invalid_pairs += wxString::Format(_L(" - %s:\n    %s first layer %d %s, other layers %d %s\n    %s max delta %d %s, current delta %d %s\n"),
7307	                                          rule.label, bullet, first_temp, deg_c, other_temp, deg_c, bullet, rule.max_delta, deg_c, delta, deg_c);
7308	        ++invalid_count;
7309	    }
7310	
7311	    if (invalid_count == 0)
7312	        return true;
7313	
7314	    wxString msg_text = _L("Some first-layer and other-layer temperature pairs exceed safety limits.\n");
7315	    msg_text += _L("\nInvalid pairs:\n");
7316	    msg_text += invalid_pairs;
7317	    msg_text += _L("\nYou can go back to edit values, or continue if this is intentional.");
7318	    msg_text += _L("\n\nContinue anyway?");
7319	
7320	    RichMessageDialog dialog(parent(), msg_text, _L("Temperature Safety Check"), wxYES | wxNO | wxICON_WARNING);
7321	    dialog.SetButtonLabel(wxID_YES, _L("Continue"), true);
7322	    dialog.SetButtonLabel(wxID_NO, _L("Back"));
7323	    dialog.ShowCheckBox(_L("Don't warn again for this preset"));
7324	    const int answer = dialog.ShowModal();
7325	    // Session-only suppression (does not modify/save filament preset data).
7326	    if (dialog.IsCheckBoxChecked() && !suppress_key.empty())
7327	        s_filament_temp_pair_warning_suppressed_for_session.insert(suppress_key);
7328	
7329	    return answer == wxID_YES;
7330	}
