1244	bool Sidebar::priv::switch_diameter(bool single)
1245	{
1246	    wxString diameter;
1247	    if (single) {
1248	        diameter = single_extruder->combo_diameter->GetValue();
1249	    } else {
1250	        auto diameter_left = left_extruder->combo_diameter->GetValue();
1251	        auto diameter_right = right_extruder->combo_diameter->GetValue();
1252	        if (diameter_left != diameter_right) {
1253	            std::string printer_type = wxGetApp().preset_bundle->printers.get_edited_preset().get_printer_type(wxGetApp().preset_bundle);
1254	            auto left_name  = _L(DevPrinterConfigUtil::get_toolhead_display_name(printer_type, DEPUTY_EXTRUDER_ID, ToolHeadComponent::Nozzle, ToolHeadNameCase::SentenceCase));
1255	            auto right_name = _L(DevPrinterConfigUtil::get_toolhead_display_name(printer_type, MAIN_EXTRUDER_ID, ToolHeadComponent::Nozzle, ToolHeadNameCase::SentenceCase));
1256	            MessageDialog dlg(this->plater,
1257	                              _L("The software does not support using different diameter of nozzles for one print. "
1258	                                 "If the left and right nozzles are inconsistent, we can only proceed with single-head printing. "
1259	                                 "Please confirm which nozzle you would like to use for this project."),
1260	                              _L("Switch diameter"), wxYES_NO | wxNO_DEFAULT);
1261	            dlg.SetButtonLabel(wxID_YES, wxString::Format("%s: %smm", left_name, diameter_left));
1262	            dlg.SetButtonLabel(wxID_NO, wxString::Format("%s: %smm", right_name, diameter_right));
1263	            int result = dlg.ShowModal();
1264	            if (result == wxID_YES)
1265	                diameter = diameter_left;
1266	            else if (result == wxID_NO)
1267	                diameter = diameter_right;
1268	            else
1269	                return false;
1270	        }
1271	        else {
1272	            diameter = diameter_left;
1273	        }
1274	    }
1275	    
1276	    // ORCA: Check if the selected diameter matches the current nozzle diameter in the config
1277	    Preset& printer_preset = wxGetApp().preset_bundle->printers.get_edited_preset();
1278	    auto* nozzle_diameter = dynamic_cast<const ConfigOptionFloats*>(printer_preset.config.option("nozzle_diameter"));
1279	    if (nozzle_diameter && nozzle_diameter->size() > 0) {
1280	        auto current_nozzle_dia = get_diameter_string(nozzle_diameter->values[0]);
1281	        // If the selected diameter is the same as current nozzle, don't switch profiles
1282	        if (current_nozzle_dia == diameter.ToStdString()) {
1283	            return true;
1284	        }
1285	    }
1286	    
1287	    auto preset          = wxGetApp().preset_bundle->get_similar_printer_preset({}, diameter.ToStdString());
1288	    if (preset == nullptr) {
1289	        // ORCA add a text. this appears when user tries to change nozzle value but config doesnt have a inherited or compatible preset
1290	        MessageDialog dlg(this->plater, _L("Configuration incompatible"), _L("Warning"), wxICON_WARNING | wxOK);
1291	        dlg.ShowModal();
1292	        return false;
1293	    }
1294	    preset->is_visible = true; // force visible
1295	    return wxGetApp().get_tab(Preset::TYPE_PRINTER)->select_preset(preset->name);
1296	}
