4118	void Sidebar::auto_calc_flushing_volumes(const int filament_idx, const int extruder_id) {
4119	
4120	    std::vector<int> filament_indices;
4121	    std::vector<int> extruder_indices;
4122	
4123	    auto& preset_bundle = wxGetApp().preset_bundle;
4124	    auto filament_ptr = preset_bundle->project_config.option<ConfigOptionStrings>("filament_colour");
4125	    int filament_count = filament_ptr ? filament_ptr->size() : 0;
4126	    int extruder_count = preset_bundle->get_printer_extruder_count();
4127	
4128	    if (filament_idx < 0) {
4129	        filament_indices.resize(filament_count);
4130	        std::iota(filament_indices.begin(), filament_indices.end(), 0);
4131	    }
4132	    else {
4133	        filament_indices.emplace_back(filament_idx);
4134	    }
4135	
4136	    if (extruder_id < 0) {
4137	        extruder_indices.resize(extruder_count);
4138	        std::iota(extruder_indices.begin(), extruder_indices.end(), 0);
4139	    }
4140	    else {
4141	        extruder_indices.emplace_back(extruder_id);
4142	    }
4143	
4144	    for (auto eidx : extruder_indices) {
4145	        for (auto fidx : filament_indices) {
4146	            auto_calc_flushing_volumes_internal(fidx, eidx);
4147	        }
4148	    }
4149	
4150	    wxGetApp().preset_bundle->export_selections(*wxGetApp().app_config);
4151	    wxGetApp().plater()->update_project_dirty_from_presets();
4152	    wxPostEvent(this, SimpleEvent(EVT_SCHEDULE_BACKGROUND_PROCESS, this));
4153	    auto has_modify = is_flush_config_modified();
4154	    set_flushing_volume_warning(has_modify);
4155	    p->plater->update();
4156	}
