8248	// This is called when creating new project or load another project
8249	// OR close ConfigWizard
8250	// to ask the user what should we do with unsaved changes for presets.
8251	// New Project          => Current project is saved    => UnsavedChangesDialog: "Keep / Discard / Cancel"
8252	//                      => Current project isn't saved => UnsavedChangesDialog: "Keep / Discard / Save / Cancel"
8253	// Close ConfigWizard   => Current project is saved    => UnsavedChangesDialog: "Keep / Discard / Save / Cancel"
8254	// Note: no_nullptr postponed_apply_of_keeped_changes indicates that thie function is called after ConfigWizard is closed
8255	bool GUI_App::check_and_keep_current_preset_changes(const wxString& caption, const wxString& header, int action_buttons, bool* postponed_apply_of_keeped_changes/* = nullptr*/)
8256	{
8257	    if (has_current_preset_changes()) {
8258	        bool is_called_from_configwizard = postponed_apply_of_keeped_changes != nullptr;
8259	
8260	        UnsavedChangesDialog dlg(caption, header, "", action_buttons);
8261	        bool no_need_change = dlg.getUpdateItemCount() == 0 ? true : false;
8262	        if (!no_need_change && dlg.ShowModal() == wxID_CANCEL)
8263	            return false;
8264	
8265	        auto reset_modifications = [this, is_called_from_configwizard]() {
8266	            //if (is_called_from_configwizard)
8267	            //    return; // no need to discared changes. It will be done fromConfigWizard closing
8268	
8269	            PrinterTechnology printer_technology = preset_bundle->printers.get_edited_preset().printer_technology();
8270	            for (const Tab* const tab : tabs_list) {
8271	                if (tab->supports_printer_technology(printer_technology) && tab->current_preset_is_dirty())
8272	                    tab->m_presets->discard_current_changes();
8273	            }
8274	            load_current_presets(false);
8275	        };
8276	
8277	        if (dlg.discard() || no_need_change)
8278	            reset_modifications();
8279	        else  // save selected changes
8280	        {
8281	            //BBS: add project embedded preset relate logic
8282	            const auto& preset_names_and_types = dlg.get_names_and_types();
8283	            if (dlg.save_preset()) {
8284	                for (const UnsavedChangesDialog::PresetData& nt : preset_names_and_types)
8285	                    preset_bundle->save_changes_for_preset(nt.name, nt.type, dlg.get_unselected_options(nt.type), nt.save_to_project);
8286	
8287	                // if we saved changes to the new presets, we should to
8288	                // synchronize config.ini with the current selections.
8289	                preset_bundle->export_selections(*app_config);
8290	
8291	                //wxString text = _L_PLURAL("Modifications to the preset have been saved",
8292	                //    "Modifications to the presets have been saved", preset_names_and_types.size());
8293	                //if (!is_called_from_configwizard)
8294	                //    text += "\n\n" + _L("All modifications will be discarded for new project.");
8295	
8296	                //MessageDialog(nullptr, text).ShowModal();
8297	                reset_modifications();
8298	            }
8299	            else if (dlg.transfer_changes() && (dlg.has_unselected_options() || is_called_from_configwizard)) {
8300	                // execute this part of code only if not all modifications are keeping to the new project
8301	                // OR this function is called when ConfigWizard is closed and "Keep modifications" is selected
8302	                for (const UnsavedChangesDialog::PresetData& nt : preset_names_and_types) {
8303	                    Preset::Type type = nt.type;
8304	                    Tab* tab = get_tab(type);
8305	                    std::vector<std::string> selected_options = dlg.get_selected_options(type);
8306	                    if (type == Preset::TYPE_PRINTER) {
8307	                        auto it = std::find(selected_options.begin(), selected_options.end(), "extruders_count");
8308	                        if (it != selected_options.end()) {
8309	                            // erase "extruders_count" option from the list
8310	                            selected_options.erase(it);
8311	                            // cache the extruders count
8312	                            static_cast<TabPrinter*>(tab)->cache_extruder_cnt();
8313	                        }
8314	                    }
8315	                    std::vector<std::string> selected_options2;
8316	                    std::transform(selected_options.begin(), selected_options.end(), std::back_inserter(selected_options2), [](auto & o) {
8317	                        auto i = o.find('#');
8318	                        return i != std::string::npos ? o.substr(0, i) : o;
8319	                    });
8320	                    tab->cache_config_diff(selected_options2);
8321	                    if (!is_called_from_configwizard)
8322	                        tab->m_presets->discard_current_changes();
8323	                }
8324	                if (is_called_from_configwizard)
8325	                    *postponed_apply_of_keeped_changes = true;
8326	                else
8327	                    apply_keeped_preset_modifications();
