25	bool answer_through_scope(wxWindow& dialog, int& answer)
26	{
27	    if (g_innermost == nullptr || !wxIsMainThread())
28	        return false;
29	    const wxTopLevelWindow* window = dynamic_cast<wxTopLevelWindow*>(&dialog);
30	    const wxString          title  = window != nullptr ? window->GetTitle() : wxString();
31	    answer = g_innermost->m_decide(dialog, title);
32	    g_innermost->m_records.push_back({title.ToUTF8().data(), answer});
33	    return true;
34	}
