624	CommandResult OrcaWorkspaceAdapter::apply_printer_setup(const PrinterSetupRequest& request, PrinterSetupPreview& applied)
625	{
626	    wxASSERT(wxIsMainThread());
627	    const PrinterSetupPreview preview = preview_printer_setup(request);
628	    if (!preview.valid)
629	        return CommandResult::failure(WorkspaceError::InvalidArgument, preview.issues.front().message);
630	    if (!preview.unsaved_edits.empty() && !request.discard_unsaved_edits)
631	        return CommandResult::failure(WorkspaceError::InvalidArgument, "Unsaved preset edits would be lost.");
632	    PresetBundle* bundle = wxGetApp().preset_bundle;
633	    const auto tab = [](Preset::Type type) { return wxGetApp().get_tab(type); };
634	
635	    // Tab::select_preset asks about unsaved edits in a modal. The caller has
636	    // already said to drop them, so they are dropped first and nothing asks.
637	    for (const UnsavedEdits& edits : preview.unsaved_edits) {
638	        const Preset::Type type = edits.kind == "printer" ? Preset::TYPE_PRINTER :
639	                                  edits.kind == "process" ? Preset::TYPE_PRINT : Preset::TYPE_FILAMENT;
640	        if (Tab* owner = tab(type)) {
641	            owner->get_presets()->discard_current_changes();
642	            owner->load_current_preset();
643	        }
644	    }
645	
646	    const std::string previous_process = current_process_preset();
647	    const std::string previous_plate   = configured_printer().plate_type;
648	    const std::vector<std::string> previous_filaments = bundle->filament_presets;
649	    {
650	        const ProjectStateTransaction transaction = m_plater.project_state_transaction();
651	        if (request.printer_preset && !SetupCommands::select_printer_preset(m_plater, *request.printer_preset))
652	            return CommandResult::failure(WorkspaceError::UnavailableOperation, "OrcaSlicer did not select the printer.");
653	        if (request.plate_type) {
654	            const ConfigOptionDef* definition = print_config_def.get("curr_bed_type");
655	            int value = 0;
656	            for (int index = 0; definition != nullptr && index < int(definition->enum_labels.size()); ++index)
657	                if (definition->enum_labels[index] == preview.resulting.plate_type)
658	                    value = index + 1;
659	            if (value == 0 || !SetupCommands::select_bed_type(m_plater, value))
660	                return CommandResult::failure(WorkspaceError::UnavailableOperation, "OrcaSlicer did not select the plate.");
661	        }
662	        if (request.process_preset && *request.process_preset != current_process_preset()) {
663	            // The process branch of Plater::priv::on_select_preset.
664	            tab(Preset::TYPE_PRINT)->select_preset(*request.process_preset);
665	            m_plater.on_config_change(bundle->full_config());
666	        }
667	        if (request.filament_presets)
668	            for (std::size_t slot = 0; slot < request.filament_presets->size(); ++slot) {
669	                const std::string& name = (*request.filament_presets)[slot];
670	                if (slot < bundle->filament_presets.size() && bundle->filament_presets[slot] == name)
671	                    continue;
672	                // The same path the header's filament menu takes, so a slot
673	                // changed by the agent gets Orca's colour rule too.
674	                if (!SetupCommands::select_filament_preset(m_plater, slot, name))
675	                    return CommandResult::failure(WorkspaceError::UnavailableOperation, "OrcaSlicer did not select the filament.");
676	            }
677	        m_plater.notify_project_state_changed(ProjectStateChangeReason::Settings);
678	    }
679	
680	    // What actually happened, read back rather than predicted.
681	    applied            = preview;
682	    applied.resulting  = configured_printer();
683	    applied.process_preset = current_process_preset();
684	    applied.substitutions.clear();
685	    if (!request.process_preset && applied.process_preset != previous_process)
686	        applied.substitutions.push_back({"process", previous_process, "replaced with " + applied.process_preset});
687	    if (!request.plate_type && applied.resulting.plate_type != previous_plate)
688	        applied.substitutions.push_back({"plate", previous_plate, "replaced with " + applied.resulting.plate_type});
689	    for (std::size_t slot = 0; slot < previous_filaments.size() && slot < bundle->filament_presets.size(); ++slot) {
690	        const bool requested = request.filament_presets && slot < request.filament_presets->size();
691	        if (!requested && bundle->filament_presets[slot] != previous_filaments[slot])
692	            applied.substitutions.push_back({"filament", previous_filaments[slot], "replaced with " + bundle->filament_presets[slot]});
693	    }
694	    return CommandResult::success();
695	}
