698	// Runs an Orca job unchanged and says how it ended. Orca's worker has no
699	// completion event; finalize runs on the UI thread, and a job dropped from
700	// the queue by a later replace_job is never finalized, which the destructor
701	// reports as cancelled.
702	class ReportingJob final : public Job
703	{
704	public:
705	    using Done = std::function<void(const char*)>;
706	    ReportingJob(std::unique_ptr<Job> inner, Done done) : m_inner(std::move(inner)), m_done(std::move(done)) {}
707	    ~ReportingJob() override
708	    {
709	        if (!m_reported) m_done("cancelled");
710	    }
711	    void process(Ctl& ctl) override { m_inner->process(ctl); }
712	    void finalize(bool canceled, std::exception_ptr& eptr) override
713	    {
714	        m_inner->finalize(canceled, eptr);
715	        m_reported = true;
716	        m_done(canceled ? "cancelled" : eptr ? "failed" : "finished");
717	    }
718	
719	private:
720	    std::unique_ptr<Job> m_inner;
721	    Done                 m_done;
722	    bool                 m_reported{false};
723	};
724	
725	bool OrcaWorkspaceAdapter::start_job(const std::string& handle, const std::string& kind, std::unique_ptr<Job> job)
726	{
727	    Worker& worker = m_plater.get_ui_job_worker();
728	    if (!worker.is_idle())
729	        return false;
730	    if (m_jobs.size() == kJobLimit)
731	        m_jobs.erase(m_jobs.begin());
732	    m_jobs.push_back({handle, kind, "running", {}});
733	    std::weak_ptr<bool> alive = m_alive;
734	    replace_job(worker, std::make_shared<ReportingJob>(std::move(job), [this, alive, handle](const char* state) {
735	        if (!alive.expired())
736	            finish_job(handle, state);
737	    }));
738	    return true;
739	}
