741	void OrcaWorkspaceAdapter::finish_job(const std::string& handle, const char* state)
742	{
743	    const auto job = std::find_if(m_jobs.begin(), m_jobs.end(), [&](const WorkspaceJob& j) { return j.handle == handle; });
744	    if (job == m_jobs.end() || job->state != "running")
745	        return;
746	    job->state = state;
747	    if (job->kind == "arrange" && m_arrange_restore) {
748	        GLCanvas3D::ArrangeSettings& settings = m_plater.canvas3D()->get_arrange_settings();
749	        settings.distance        = m_arrange_restore->first;
750	        settings.enable_rotation = m_arrange_restore->second;
751	        m_arrange_restore.reset();
752	    }
753	    if (job->kind == "arrange" && job->state == "finished") {
754	        // Orca moves what does not fit onto a new plate or off the plates; an
755	        // instance no plate holds entirely is what did not fit.
756	        PartPlateList&         plates  = m_plater.get_partplate_list();
757	        const ModelObjectPtrs& objects = m_plater.model().objects;
758	        for (std::size_t index = 0; index < objects.size(); ++index)
759	            for (std::size_t instance = 0; instance < objects[index]->instances.size(); ++instance)
760	                if (objects[index]->instances[instance]->printable &&
761	                    plates.find_instance_belongs(static_cast<int>(index), static_cast<int>(instance)) < 0) {
762	                    job->not_placed.push_back(ObjectId(m_session, objects[index]->id().id));
763	                    break;
764	                }
765	    }
766	    publish_change(WorkspaceChangeReasons::Plates | WorkspaceChangeReasons::Transform);
767	}
