1696	    // Orca asks about edited presets in UnsavedChangesDialog, whose answer is
1697	    // read from the dialog afterwards; dropping the edits first means it is
1698	    // never asked.
1699	    if (request.discard_unsaved)
1700	        for (Preset::Type type : {Preset::TYPE_PRINTER, Preset::TYPE_PRINT, Preset::TYPE_FILAMENT})
1701	            if (Tab* tab = wxGetApp().get_tab(type); tab != nullptr && tab->get_presets()->current_is_dirty()) {
1702	                tab->get_presets()->discard_current_changes();
