1708	        return answer_load_question(dialog, title, request.units, request.scale_oversized, request.discard_unsaved);
1709	    });
1710	
1711	    bool loaded = true;
1712	    if (request.new_project) {
1713	        loaded = m_plater.new_project(true, true) != wxID_CANCEL;
1714	    } else if (extension == ".3mf") {
1715	        // "<loadall>" is Orca's own way to open a project with its settings
1716	        // without asking how ("<silence>" would also leave the project
1717	        // without its file name); geometry only is the answer the person
1718	        // would otherwise give in ProjectDropDialog, set for this one load.
