1829	CommandResult OrcaWorkspaceAdapter::delete_items(const std::vector<DeleteItem>& items)
1830	{
1831	    wxASSERT(wxIsMainThread());
1832	    Model&         model  = m_plater.model();
1833	    PartPlateList& plates = m_plater.get_partplate_list();
1834	    std::vector<ItemForDelete> subitems;
1835	    std::vector<std::size_t>   objects;
1836	    std::vector<int>           plate_indices;
1837	    std::map<std::size_t, std::pair<std::size_t, std::size_t>> removing; // object -> (model parts, instances)
1838	
1839	    // Everything is checked first. Orca reports some refusals from these
1840	    // paths with an error it shows after the call returns, which no answer
1841	    // can reach, so the same conditions are refused here.
1842	    for (const DeleteItem& item : items) {
1843	        if (item.kind == DeleteItem::Kind::Plate) {
1844	            int index = -1;
1845	            for (int candidate = 0; candidate < plates.get_plate_count(); ++candidate)
1846	                if (item.plate.session() == m_session && plates.get_plate(candidate)->id().id == item.plate.value())
1847	                    index = candidate;
1848	            if (index < 0)
1849	                return CommandResult::failure(WorkspaceError::StaleId, "That plate is not in the open project");
1850	            plate_indices.push_back(index);
1851	            continue;
1852	        }
1853	        const auto resolved = resolve(item.object);
1854	        if (!resolved)
1855	            return id_error(item.object);
1856	        const ModelObject& object = *model.objects[resolved->index];
1857	        if (item.kind == DeleteItem::Kind::Object) {
1858	            objects.push_back(resolved->index);
1859	        } else if (item.kind == DeleteItem::Kind::Part) {
1860	            const auto volume = std::find_if(object.volumes.begin(), object.volumes.end(),
1861	                                             [&](const ModelVolume* v) { return v->id().id == item.part; });
1862	            if (volume == object.volumes.end())
1863	                return CommandResult::failure(WorkspaceError::StaleId, "That part is not in " + object.name);
1864	            if (object.is_cut() && ((*volume)->is_model_part() || (*volume)->is_negative_volume()))
1865	                return CommandResult::failure(WorkspaceError::UnavailableOperation,
1866	                                              "OrcaSlicer does not delete the solid parts of a cut object");
1867	            if ((*volume)->is_model_part())
1868	                ++removing[resolved->index].first;
1869	            subitems.emplace_back(itVolume, int(resolved->index), int(volume - object.volumes.begin()));
1870	        } else {
1871	            if (item.instance >= object.instances.size())
1872	                return CommandResult::failure(WorkspaceError::InvalidArgument, object.name + " has no such copy");
1873	            ++removing[resolved->index].second;
1874	            subitems.emplace_back(itInstance, int(resolved->index), int(item.instance));
1875	        }
1876	    }
1877	    std::sort(objects.begin(), objects.end());
1878	    objects.erase(std::unique(objects.begin(), objects.end()), objects.end());
1879	    // Parts and copies of an object that goes whole need no separate step.
1880	    subitems.erase(std::remove_if(subitems.begin(), subitems.end(), [&](const ItemForDelete& item) {
1881	                       return std::binary_search(objects.begin(), objects.end(), std::size_t(item.obj_idx));
1882	                   }),
1883	                   subitems.end());
1884	    for (const auto& [index, counts] : removing) {
1885	        if (std::binary_search(objects.begin(), objects.end(), index))
1886	            continue;
1887	        const ModelObject& object = *model.objects[index];
1888	        const auto parts = std::count_if(object.volumes.begin(), object.volumes.end(), [](const ModelVolume* v) { return v->is_model_part(); });
1889	        if (counts.first >= std::size_t(parts))
1890	            return CommandResult::failure(WorkspaceError::InvalidArgument,
1891	                                          "That would remove every solid part of " + object.name + "; delete the object instead");
1892	        if (counts.second >= object.instances.size())
1893	            return CommandResult::failure(WorkspaceError::InvalidArgument,
1894	                                          "That would remove every copy of " + object.name + "; delete the object instead");
1895	    }
1896	    std::sort(plate_indices.begin(), plate_indices.end());
1897	    plate_indices.erase(std::unique(plate_indices.begin(), plate_indices.end()), plate_indices.end());
1898	    if (!plate_indices.empty() && plate_indices.size() >= std::size_t(plates.get_plate_count()))
1899	        return CommandResult::failure(WorkspaceError::InvalidArgument, "A project keeps at least one plate");
1900	
1901	    {
1902	        const ProjectStateTransaction transaction = m_plater.project_state_transaction();
1903	        Plater::TakeSnapshot snapshot(&m_plater, "Delete items");
1904	        // The card named a cut object's broken correspondence already.
1905	        ScopedModalAnswers answers([](wxWindow&, const wxString& title) {
1906	            return title == _L("Delete object which is a part of cut object") ? int(wxID_YES) : int(wxID_NO);
1907	        });
1908	        if (!subitems.empty()) {
1909	            // The object list deletes in reverse order, so it gets them sorted.
1910	            std::sort(subitems.begin(), subitems.end(), [](const ItemForDelete& a, const ItemForDelete& b) {
1911	                return std::tie(a.obj_idx, a.type, a.sub_obj_idx) < std::tie(b.obj_idx, b.type, b.sub_obj_idx);
1912	            });
1913	            wxGetApp().obj_list()->delete_from_model_and_list(subitems);
1914	        }
1915	        for (auto index = objects.rbegin(); index != objects.rend(); ++index)
1916	            if (!m_plater.delete_object(*index))
1917	                return CommandResult::failure(WorkspaceError::UnavailableOperation, "OrcaSlicer did not delete an object");
1918	        // A deleted plate's objects move to another plate, as in Orca.
1919	        for (auto index = plate_indices.rbegin(); index != plate_indices.rend(); ++index)
1920	            m_plater.delete_plate(*index);
1921	        m_plater.notify_project_state_changed(ProjectStateChangeReason::Objects | ProjectStateChangeReason::Plates);
1922	    }
1923	    return CommandResult::success();
1924	}
