2408	CommandResult OrcaWorkspaceAdapter::apply_settings(const SettingsPatch& patch, const std::vector<SettingChange>& confirmed,
2409	                                                  SettingsPreview& applied)
2410	{
2411	    wxASSERT(wxIsMainThread());
2412	    const SettingsScope scope = patch.target.scope;
2413	    if (preset_scope(scope) ? !fff_printer() : !process_settings_available())
2414	        return CommandResult::failure(WorkspaceError::UnavailableOperation, unavailable(scope).message);
2415	    const PresetOwner owner = preset_owner(patch.target);
2416	    if (owner.preset == nullptr)
2417	        return CommandResult::failure(WorkspaceError::StaleSettings, "The preset is gone. Read and preview again.");
2418	    auto transaction = m_plater.project_state_transaction();
2419	    ModelObject* object = settings_object(patch.target);
2420	    DynamicPrintConfig effective = owner_config(owner);
2421	    if (object)
2422	        effective.apply(object->config.get());
2423	    for (const auto& change : confirmed)
2424	        if (!effective.option(change.key) || effective.option(change.key)->serialize() != change.before)
2425	            return CommandResult::failure(WorkspaceError::StaleSettings, "A confirmed setting changed. Read and preview again.");
2426	    applied = preview_settings(patch);
2427	    if (!applied.valid)
2428	        return CommandResult::failure(WorkspaceError::InvalidSettings, "The settings patch is invalid.");
2429	    const auto actual = settings_confirmation(applied);
2430	    if (actual.size() != confirmed.size() || !std::equal(actual.begin(), actual.end(), confirmed.begin(),
2431	        [](const auto& a, const auto& b) { return a.key == b.key && a.before == b.before && a.after == b.after; }))
2432	        return CommandResult::failure(WorkspaceError::StaleSettings, "The patch no longer matches the approved preview.");
2433	    if (applied.changes.empty())
2434	        return CommandResult::failure(WorkspaceError::NoChange, "All requested values are unchanged.");
2435	    if (object) {
2436	        // ObjectSettings' write, as an undo step: the override lands in the
2437	        // object's ModelConfig, the list shows its settings item, and the
2438	        // object's slicing is invalidated.
2439	        Plater::TakeSnapshot snapshot(&m_plater, "Change object settings");
2440	        for (const auto& change : applied.changes) {
2441	            DynamicPrintConfig value;
2442	            value.set_deserialize_strict(change.key, change.after);
2443	            object->config.set_key_value(change.key, value.option(change.key)->clone());
2444	        }
