180	// Audit against ConfigManipulation::update_print_fff_config. These are every
181	// active modal predicate, including unrelated pre-existing invalid values:
182	// update() evaluates the entire config after any allowed batch. Keep refusal
183	// here; the live normalizer remains unchanged and owns its UI behavior.
184	inline void check_process_dialogs(const DynamicPrintConfig& config, SettingsPreview& result)
185	{
186	    const auto block = [&](bool condition, const std::string& key, const std::string& message) {
187	        if (condition) result.issues.push_back({key, "incompatible_settings", message});
188	    };
189	    const double height = config.opt_float("layer_height");
190	    const auto& printer = wxGetApp().preset_bundle->printers.get_edited_preset().config;
191	    const double maximum = printer.opt_float("max_layer_height", 0);
192	    if (height < EPSILON)
193	        result.issues.push_back({"layer_height", "invalid_setting_value", "Layer height is below Orca's minimum.", {}, {}, EPSILON, {}});
194	    if (maximum > 0.2 && height > maximum + EPSILON)
195	        result.issues.push_back({"layer_height", "invalid_setting_value", "Layer height exceeds the printer maximum.", {}, {}, {}, maximum});
196	    for (const auto* key : {"ironing_spacing", "support_ironing_spacing"})
197	        block(config.opt_float(key) < 0.05, key, "Ironing spacing would open Orca's correction dialog; correct it first.");
198	    block(config.opt_float("initial_layer_print_height") < EPSILON, "initial_layer_print_height", "Initial layer height would open Orca's correction dialog.");
199	    for (const auto* key : {"xy_hole_compensation", "xy_contour_compensation"})
200	        block(std::abs(config.opt_float(key)) > 2, key, "XY compensation would open Orca's correction dialog.");
201	    block(config.opt_float("elefant_foot_compensation") > 1, "elefant_foot_compensation", "Elephant foot compensation would open Orca's correction dialog.");
202	    block(config.opt_bool("spiral_mode") && !(config.opt_int("wall_loops") == 1 && config.opt_int("top_shell_layers") == 0 &&
203	        config.option<ConfigOptionPercent>("sparse_infill_density")->value == 0 && !config.opt_bool("enable_support") &&
204	        config.opt_int("enforce_support_layers") == 0 && !config.opt_bool("detect_thin_wall") && !config.opt_bool("overhang_reverse") &&
205	        config.opt_enum<TimelapseType>("timelapse_type") == tlTraditional && !config.opt_bool("enable_wrapping_detection")),
206	        "spiral_mode", "Spiral mode conflicts with wall_loops, top_shell_layers, infill, support, thin walls, overhang reversal, timelapse, or wrapping detection.");
207	    block(config.opt_bool("alternate_extra_wall") && config.opt_enum<EnsureVerticalShellThickness>("ensure_vertical_shell_thickness") == evstAll,
208	        "alternate_extra_wall", "Alternate extra wall conflicts with ensure_vertical_shell_thickness=all.");
209	    block(config.opt_enum<SeamScarfType>("seam_slope_type") != SeamScarfType::None && config.get_abs_value("seam_slope_start_height") >= height,
210	        "layer_height", "Layer height conflicts with seam_slope_type and seam_slope_start_height; scarf start height must be below layer height.");
211	    block(config.opt_float("infill_lock_depth") > config.opt_float("skin_infill_depth"), "infill_lock_depth", "Infill lock depth exceeds skin_infill_depth.");
212	    block(config.opt_enum<FuzzySkinMode>("fuzzy_skin_mode") != FuzzySkinMode::Displacement &&
213	        config.opt_enum<PerimeterGeneratorType>("wall_generator") != PerimeterGeneratorType::Arachne,
214	        "fuzzy_skin_mode", "This fuzzy skin mode requires wall_generator=arachne.");
215	}
