217	// ConfigManipulation resets support_style to default, silently, when it does
218	// not fit the support type. A patch that would be rewritten that way is
219	// refused with the styles that fit, rather than approved and then changed.
220	inline void check_support_style(const DynamicPrintConfig& config, const std::map<std::string, std::string>& patch,
221	                                SettingsPreview& result)
222	{
223	    if (!config.opt_bool("enable_support") ||
224	        (!patch.count("support_style") && !patch.count("support_type") && !patch.count("enable_support")))
225	        return;
226	    const bool tree = is_tree(config.opt_enum<SupportType>("support_type"));
227	    const std::vector<SupportMaterialStyle> fitting = tree ?
228	        std::vector<SupportMaterialStyle>{smsDefault, smsTreeSlim, smsTreeStrong, smsTreeHybrid, smsTreeOrganic} :
229	        std::vector<SupportMaterialStyle>{smsDefault, smsGrid, smsSnug};
230	    const auto style = config.opt_enum<SupportMaterialStyle>("support_style");
231	    if (std::find(fitting.begin(), fitting.end(), style) != fitting.end())
232	        return;
233	    std::vector<std::string> allowed;
234	    for (SupportMaterialStyle candidate : fitting)
235	        allowed.push_back(ConfigOptionEnum<SupportMaterialStyle>(candidate).serialize());
236	    result.issues.push_back({"support_style", "invalid_setting_value",
237	                             std::string("With ") + (tree ? "tree" : "normal") +
238	                                 " supports, support_style must be one of the allowed values; OrcaSlicer would reset it to default.",
239	                             allowed});
240	}
