256	inline void predict_process_normalization(DynamicPrintConfig& config)
257	{
258	    // The modal predicates above were checked first. Execute Orca's own
259	    // normalization on the clone with no presentation callbacks; don't keep
260	    // a duplicate table of dependent values or infill-pattern capabilities.
261	    ConfigManipulation normalizer([] {}, [](const std::string&, bool, int) {}, {}, {});
262	    auto& bundle = *wxGetApp().preset_bundle;
263	    const auto& selected = bundle.prints.get_selected_preset();
264	    normalizer.initialize_support_material_overhangs_queried(!selected.is_system && !selected.is_dirty &&
265	        config.opt_bool("enable_support") && !config.opt_bool("detect_overhang_wall"));
266	    normalizer.set_is_BBL_Printer(bundle.is_bbl_vendor());
267	    normalizer.update_print_fff_config(&config, true, false);
268	    if (process_tab_toggles_options(*wxGetApp().get_tab(Preset::TYPE_PRINT)))
269	        normalizer.toggle_print_fff_options(&config, true);
270	}
