272	// The filament tab's dialogs, refused before they could open.
273	// ConfigManipulation::check_filament_max_volumetric_speed resets a speed
274	// below 0.5 behind a warning on every load; Tab::save_preset asks to continue
275	// when a first-layer temperature is further than Tab::
276	// validate_filament_temperature_pairs allows from the other layers' (30 °C
277	// on the nozzle, 15 °C on a plate), both above zero.
278	inline void check_filament_dialogs(const DynamicPrintConfig& config, bool saving, SettingsPreview& result)
279	{
280	    if (config.has("filament_max_volumetric_speed") && config.opt_float("filament_max_volumetric_speed", 0) < 0.5)
281	        result.issues.push_back({"filament_max_volumetric_speed", "invalid_setting_value",
282	                                 "Orca resets a max volumetric speed below 0.5 to 0.5.", {}, {}, 0.5, {}});
283	    if (!saving)
284	        return;
285	    std::vector<std::tuple<std::string, std::string, int>> pairs{{"nozzle_temperature_initial_layer", "nozzle_temperature", 30}};
286	    for (int bed = int(btPC); bed < int(btCount); ++bed) {
287	        const std::string first = get_bed_temp_1st_layer_key(BedType(bed)), other = get_bed_temp_key(BedType(bed));
288	        if (!first.empty() && !other.empty())
289	            pairs.emplace_back(first, other, 15);
290	    }
291	    for (const auto& [first_key, other_key, limit] : pairs) {
292	        const auto* first = config.option<ConfigOptionInts>(first_key);
293	        const auto* other = config.option<ConfigOptionInts>(other_key);
294	        if (first == nullptr || other == nullptr || first->values.empty() || other->values.empty())
295	            continue;
296	        const int a = first->get_at(0), b = other->get_at(0);
297	        if (a > 0 && b > 0 && std::abs(a - b) > limit)
298	            result.issues.push_back({first_key, "incompatible_settings",
299	                                     first_key + " and " + other_key + " may differ by at most " + std::to_string(limit) +
300	                                         " °C; Orca asks before saving a larger difference."});
301	    }
302	}
