100	// Case-folded for a substring search over ASCII keys and labels. Not a
101	// locale-aware fold: Orca's setting keys are ASCII, and a preset name that is
102	// not still matches on the part that is.
103	inline std::string ascii_lower(std::string text)
104	{
105	    std::transform(text.begin(), text.end(), text.begin(), [](unsigned char ch) { return std::tolower(ch); });
106	    return text;
107	}
