180	inline std::vector<std::string> setting_words(const std::string& key)
181	{
182	    std::vector<std::string> words;
183	    std::size_t start = 0;
184	    for (std::size_t end; (end = key.find('_', start)) != std::string::npos; start = end + 1)
185	        words.push_back(key.substr(start, end - start));
186	    words.push_back(key.substr(start));
187	    return words;
188	}
189	
190	inline std::vector<std::string> setting_suggestions(const std::string& key,
191	                                                    const std::vector<SettingDefinition>& definitions)
192	{
193	    // Edit distance handles misspellings, and shared words handle guessed
194	    // names ("enable_brim" for "brim_type"), without a second alias catalog.
195	    // More shared words first, writable settings before read-only ones, then
196	    // the closer spelling.
197	    using Rank = std::tuple<std::size_t, bool, std::size_t, std::string>;
198	    std::vector<Rank> ranked;
199	    const std::string needle = ascii_lower(key);
200	    const auto words = setting_words(needle);
201	    for (const auto& def : definitions) {
202	        std::vector<std::size_t> row(def.key.size() + 1);
203	        std::iota(row.begin(), row.end(), 0);
204	        for (std::size_t i = 0; i < needle.size(); ++i) {
205	            std::size_t diagonal = row[0];
206	            row[0] = i + 1;
207	            for (std::size_t j = 0; j < def.key.size(); ++j) {
208	                const auto old = row[j + 1];
209	                row[j + 1] = std::min({row[j] + 1, old + 1, diagonal + (needle[i] != def.key[j])});
210	                diagonal = old;
211	            }
212	        }
213	        // "enable" alone says nothing about which setting was meant; with a
214	        // word that does ("support_enable"), it counts.
215	        std::size_t shared = 0;
216	        bool        telling = false;
217	        for (const auto& word : words)
218	            if (word.size() >= 4 && ("_" + def.key + "_").find("_" + word + "_") != std::string::npos) {
219	                ++shared;
220	                telling = telling || word != "enable";
221	            }
222	        if (!telling)
223	            shared = 0;
224	        if (shared > 0 || row.back() <= std::max<std::size_t>(2, needle.size() / 3))
225	            ranked.emplace_back(std::numeric_limits<std::size_t>::max() - shared, !def.writable, row.back(), def.key);
226	    }
227	    std::sort(ranked.begin(), ranked.end());
228	    std::vector<std::string> result;
229	    for (std::size_t i = 0; i < std::min<std::size_t>(3, ranked.size()); ++i)
230	        result.push_back(std::get<3>(ranked[i]));
231	    return result;
232	}
