200	std::vector<FilamentInfo> compatible_filaments()
201	{
202	    std::vector<FilamentInfo> filaments;
203	    const PresetBundle* presets = wxGetApp().preset_bundle;
204	    if (presets == nullptr)
205	        return filaments;
206	    for (const Preset& preset : presets->filaments) {
207	        // is_compatible is maintained by PresetBundle::update_compatible; the
208	        // compatibility rule is never re-derived here.
209	        if (!preset.is_visible || !preset.is_compatible || preset.is_default)
210	            continue;
211	        filaments.push_back(filament_info(preset));
212	    }
213	    // Brand, then name, as the design lists them. The short name usually
214	    // starts with the brand already, so ties in brand fall through to it.
215	    std::stable_sort(filaments.begin(), filaments.end(), [](const FilamentInfo& a, const FilamentInfo& b) {
216	        const int brand = a.vendor.CmpNoCase(b.vendor);
217	        return brand != 0 ? brand < 0 : a.alias.CmpNoCase(b.alias) < 0;
218	    });
219	    return filaments;
220	}
