236	void remember_colour(const wxColour& colour)
237	{
238	    AppConfig* config = wxGetApp().app_config;
239	    if (config == nullptr || !colour.IsOk())
240	        return;
241	    // The same list, in the same form, that Orca's own colour fields read and
242	    // write (ColourPicker::save_colors_to_config), so both pickers share it.
243	    // The system picker has sixteen custom slots; the list never shrinks,
244	    // because saving overwrites entries by position and leaves any beyond.
245	    std::vector<std::string> values   = config->get_custom_color_from_config();
246	    const std::size_t        original = values.size();
247	    const std::size_t        slots    = std::max<std::size_t>(original, 16);
248	    values.erase(std::remove_if(values.begin(), values.end(),
249	                                [&](const std::string& value) { return string_to_wxColor(value) == colour; }),
250	                 values.end());
251	    values.insert(values.begin(), color_to_string(colour));
252	    if (values.size() > slots)
253	        values.resize(slots);
254	    // Refill what removing repeats freed, so no stale entry survives past the
255	    // end; a repeat reads back as nothing new.
256	    while (values.size() < original)
257	        values.push_back(values.back());
258	    config->save_custom_color_to_config(values);
259	}
