261	PrinterConnection printer_connection()
262	{
263	    PrinterConnection connection;
264	    // Non-const: use_bbl_network() is not a const member on PresetBundle.
265	    PresetBundle* presets = wxGetApp().preset_bundle;
266	    // Only the Bambu network path reports a live machine state. Every other
267	    // print host is "not connected" here, which is a statement about what
268	    // JusPrin can observe, not a claim about the machine.
269	    if (presets == nullptr || !presets->use_bbl_network())
270	        return connection;
271	    auto* devices = wxGetApp().getDeviceManager();
272	    if (devices == nullptr)
273	        return connection;
274	    MachineObject* machine = devices->get_selected_machine();
275	    if (machine == nullptr)
276	        return connection;
277	    connection.monitor_available = true;
278	    if (!machine->is_connected())
279	        connection.state = ConnectionState::Offline;
280	    else if (machine->is_in_printing())
281	        connection.state = ConnectionState::Printing;
282	    else
283	        connection.state = ConnectionState::Idle;
284	    return connection;
