310	bool select_filament_preset(Plater& plater, std::size_t slot, const std::string& preset_name)
311	{
312	    PresetBundle* presets = wxGetApp().preset_bundle;
313	    if (presets == nullptr || slot >= presets->filament_presets.size())
314	        return false;
315	    const Preset* preset = presets->filaments.find_preset(preset_name);
316	    Tab*          tab    = wxGetApp().get_tab(Preset::TYPE_FILAMENT);
317	    if (preset == nullptr || tab == nullptr)
318	        return false;
319	
320	    // The sequence the sidebar's filament combo runs, without its own repaint
321	    // and AMS badge. There is no single public Orca call for "select filament
322	    // preset N by name": the only entry point is a wxEVT_COMBOBOX carrying a
323	    // PlaterPresetComboBox as its event object, and firing that would mean
324	    // driving a hidden control. If upstream grows such a call, this body
325	    // should become one line.
326	    //
327	    // First PresetComboBox::update_ams_color, which OnSelect runs before the
328	    // selection reaches Plater: a preset that names a default colour brings it
329	    // to the slot; one that names none leaves the slot's colour as it was.
330	    const wxString default_colour = option_string(preset->config, "default_filament_colour");
331	    if (!default_colour.empty())
332	        set_filament_colour(plater, slot, wxColour(default_colour));
333	
334	    // Then the filament branch of Plater::priv::on_select_preset.
335	    const bool was_support = is_support_filament(int(slot));
336	    presets->set_filament_preset(slot, preset_name);
337	    plater.update_project_dirty_from_presets();
338	    presets->export_selections(*wxGetApp().app_config);
339	    plater.sidebar().update_dynamic_filament_list();
340	    if (was_support != is_support_filament(int(slot)) && wxGetApp().app_config->get("auto_calculate_flush") == "all")
341	        plater.sidebar().auto_calc_flushing_volumes(int(slot));
342	    plater.on_filament_change(slot);
343	    // With one slot the filament tab follows the selection; with several it
344	    // keeps its own, and only the slot lists repaint.
345	    if (presets->filament_presets.size() > 1)
346	        plater.sidebar().update_presets(Preset::TYPE_FILAMENT);
347	    else
348	        tab->select_preset(preset_name);
349	    plater.on_config_change(presets->full_config());
350	    return true;
351	}
