353	void set_filament_colour(Plater& plater, std::size_t slot, const wxColour& colour)
354	{
355	    PresetBundle* presets = wxGetApp().preset_bundle;
356	    if (presets == nullptr || !colour.IsOk() || slot >= presets->filament_presets.size())
357	        return;
358	    DynamicPrintConfig& project = presets->project_config;
359	
360	    // PlaterPresetComboBox::sync_colour_config for one slot. The three options
361	    // move together: a colour written without its type and multi-colour
362	    // siblings leaves a gradient's leftovers behind.
363	    auto patch = [&](const char* key, const std::string& value) -> ConfigOptionStrings* {
364	        auto* option = static_cast<ConfigOptionStrings*>(project.option(key)->clone());
365	        if (option->values.size() <= slot) option->values.resize(slot + 1);
366	        option->values[slot] = value;
367	        return option;
368	    };
369	    const std::string hex = colour.GetAsString(wxC2S_HTML_SYNTAX).ToStdString();
370	
371	    DynamicPrintConfig updated = project;
372	    updated.set_key_value("filament_multi_colour", patch("filament_multi_colour", hex));
373	    updated.set_key_value("filament_colour", patch("filament_colour", hex));
374	    updated.set_key_value("filament_colour_type", patch("filament_colour_type", "1")); // solid, not gradient
375	    project.apply(updated);
376	
377	    plater.update_project_dirty_from_presets();
378	    presets->export_selections(*wxGetApp().app_config);
379	    plater.on_config_change(updated);
380	
381	    auto* changed = new wxCommandEvent(EVT_FILAMENT_COLOR_CHANGED);
382	    changed->SetInt(int(slot));
383	    wxQueueEvent(&plater, changed);
384	}
