439	bool install_and_select_printer(Plater& plater, const std::string& vendor_id,
440	                                const std::string& model_id, const std::string& variant,
441	                                const std::string& default_filament, std::string& error)
442	{
443	    PresetBundle* presets = wxGetApp().preset_bundle;
444	    AppConfig* config = wxGetApp().app_config;
445	    if (!presets || !config || vendor_id.empty() || model_id.empty() || variant.empty()) {
446	        error = "Printer setup is unavailable because the preset system is not ready.";
447	        return false;
448	    }
449	    const auto old_vendors = config->vendors();
450	    const bool had_filaments = config->has_section(AppConfig::SECTION_FILAMENTS);
451	    const auto old_filaments = had_filaments ? config->get_section(AppConfig::SECTION_FILAMENTS)
452	                                             : std::map<std::string, std::string>();
453	    const std::string old_printer = presets->printers.get_selected_preset_name();
454	    auto rollback = [&]() -> std::string {
455	        config->set_vendors(old_vendors);
456	        config->set_section(AppConfig::SECTION_FILAMENTS, old_filaments);
457	        try {
458	            presets->load_presets(*config, ForwardCompatibilitySubstitutionRule::Enable,
459	                                  {std::string(), std::string(), std::string(), std::string()});
460	            if (!select_printer_preset(plater, old_printer))
461	                return "The previous printer preset could not be selected again.";
462	            if (wxGetApp().mainframe) wxGetApp().mainframe->update_side_preset_ui();
463	        } catch (const std::exception& exception) {
464	            return std::string("The previous preset configuration could not be reloaded: ") + exception.what();
465	        }
466	        return {};
467	    };
468	    try {
469	        std::map<std::string, std::map<std::string, std::set<std::string>>> vendors;
470	        vendors[vendor_id][model_id].insert(variant);
471	        std::map<std::string, std::string> filaments;
472	        if (!default_filament.empty()) filaments[default_filament] = "true";
473	        bool applied = false;
474	        bool selected = false;
475	        plater.update_objects_position_when_select_preset([&] {
476	            applied = presets->apply_vendor_config(vendors, filaments, config, false, model_id, variant,
477	                                                   default_filament);
478	            if (!applied) return;
479	            const Preset* preset = presets->printers.find_system_preset_by_model_and_variant(model_id, variant);
480	            Tab* tab = wxGetApp().get_tab(Preset::TYPE_PRINTER);
481	            if (!preset || !tab) return;
482	            tab->select_preset(preset->name);
483	            plater.on_config_change(presets->full_config());
484	            selected = true;
485	        });
486	        if (!applied) {
487	            const std::string rollback_error = rollback();
488	            error = rollback_error.empty()
489	                ? "The printer profile could not be installed. Your previous setup is unchanged."
490	                : "The printer profile could not be installed. " + rollback_error;
491	            return false;
492	        }
493	        if (!selected) {
494	            const std::string rollback_error = rollback();
495	            error = rollback_error.empty()
496	                ? "The installed profile could not be selected. Your previous setup is unchanged."
497	                : "The installed profile could not be selected. " + rollback_error;
498	            return false;
499	        }
500	        if (wxGetApp().mainframe) wxGetApp().mainframe->update_side_preset_ui();
501	        presets->export_selections(*config);
502	        return true;
503	    } catch (const std::exception& exception) {
504	        const std::string rollback_error = rollback();
505	        error = std::string("The printer profile could not be loaded: ") + exception.what();
506	        if (!rollback_error.empty()) error += " " + rollback_error;
507	        return false;
508	    }
509	}
