151	std::string OrcaPrinterBackend::add_printer(const AddPrinterRequest& request, SavedPrinter& added)
152	{
153	    // Installing and selecting the printer preset marks the open project
154	    // dirty the same way any preset switch does (Tab::select_preset ->
155	    // on_presets_changed -> update_project_dirty_from_presets), even though
156	    // nothing about the project itself changed. Only re-baseline a project
157	    // that was clean before this call, the same way Plater's own new-project
158	    // and load-project paths already do -- a real pending edit must stay
159	    // visible. And only a project with nothing saved to disk yet: for one
160	    // loaded from a file, this switch is now that project's own printer,
161	    // and re-baselining it would mean closing the project never prompts to
162	    // save that -- a real edit, made to look like nothing happened. F9 on
163	    // printer-panel-review-fixes-handoff.md.
164	    const bool was_clean       = !m_plater.is_project_dirty();
165	    const bool no_project_file = m_plater.get_project_filename().IsEmpty();
166	
167	    std::string error;
168	    if (!SetupCommands::install_and_select_printer(m_plater, request.vendor_id, request.model_id, request.variant,
169	                                                  request.material, error))
170	        return error.empty() ? std::string("This printer could not be installed.") : error;
171	
172	    if (was_clean && no_project_file) {
173	        m_plater.reset_project_dirty_initial_presets();
174	        m_plater.update_project_dirty_from_presets();
175	    }
176	
177	    const std::string name =
178	        Printers::add_named_printer(m_plater, request.name.empty() ? request.model_id : request.name, request.device_id);
179	
180	    for (const SavedPrinter& saved : saved_printers())
181	        if (saved.name == name)
182	            added = saved;
183	    return {};
184	}
