186	std::string OrcaPrinterBackend::change_printer(const ChangePrinterRequest& request, SavedPrinter& changed)
187	{
188	    std::vector<SavedPrinter> printers = saved_printers();
189	    const auto                found    = std::find_if(printers.begin(), printers.end(),
190	                                                      [&request](const SavedPrinter& saved) { return saved.name == request.name; });
191	    if (found == printers.end())
192	        return "This app no longer has a printer called \"" + request.name + "\".";
193	
194	    if (request.nozzle) {
195	        const PrinterCandidate* variant = nullptr;
196	        for (const PrinterCandidate& candidate : m_catalog.candidates())
197	            if (candidate.model_id == found->model_id && nozzle_of(candidate.variant) == *request.nozzle)
198	                variant = &candidate;
