200	            return found->model.empty() ? std::string("This printer does not come with that nozzle size.") :
201	                                          "The " + found->model + " does not come with that nozzle size.";
202	        const wxString problem = Printers::change_named_printer_nozzle(m_plater, request.name, variant->preset_name);
203	        if (!problem.empty())
204	            return problem.ToStdString();
205	    }
206	
207	    for (const SavedPrinter& saved : saved_printers())
208	        if (saved.name == request.name)
209	            changed = saved;
210	    return {};
211	}
