307	std::vector<std::string> name_installed_printers(Plater& plater, const VendorMap& before)
308	{
309	    std::vector<std::string> added;
310	    PresetBundle&     presets  = bundle();
311	    const std::string selected = presets.printers.get_selected_preset_name();
312	    const Preset&     current  = presets.printers.get_selected_preset();
313	    const auto        models   = newly_installed_models(before, wxGetApp().app_config->vendors(),
314	                                                        current.config.opt_string("printer_model"),
315	                                                        current.config.opt_string("printer_variant"));
316	    std::string keep;
317	    for (const InstalledModel& model : models) {
318	        const Preset* profile = presets.printers.find_system_preset_by_model_and_variant(model.model, model.variant);
319	        if (profile == nullptr)
320	            throw std::runtime_error("The wizard enabled " + model.model + " " + model.variant +
321	                                     " but no system profile for it is loaded");
322	        const std::string profile_name = profile->name;
323	        if (!SetupCommands::select_printer_preset(plater, profile_name) ||
324	            presets.printers.get_selected_preset_name() != profile_name)
325	            break; // keep the receipt for any printers already saved
326	        const std::string name = add_named_printer(plater, model.model, {});
327	        added.push_back(name);
328	        if (profile_name == selected)
329	            keep = name;
330	    }
331	    // Naming selects each printer in turn; the wizard's own choice is the one
332	    // left selected, under its name when it was one of them.
333	    if (!models.empty())
334	        SetupCommands::select_printer_preset(plater, keep.empty() ? selected : keep);
335	    return added;
336	}
