383	wxString change_named_printer_nozzle(Plater& plater, const std::string& name, const std::string& system_preset)
384	{
385	    PresetCollection& printers = bundle().printers;
386	    Preset*           saved    = saved_preset(name);
387	    if (saved == nullptr || !is_named_printer(*saved))
388	        return gone();
389	
390	    const Preset* old_parent = printers.get_preset_parent(*saved);
391	    // Not const: Preset::save takes its parent's config by pointer.
392	    Preset*       new_parent = printers.find_preset(system_preset, false, true);
393	    if (old_parent == nullptr || new_parent == nullptr || !new_parent->is_system)
394	        return _L("This printer does not come with that nozzle size.");
395	    if (old_parent == new_parent)
396	        return {};
397	
398	    // The open project keeps the printer it has selected, and nothing asks
399	    // the person anything: Orca's save and its unsaved-changes prompt both go
400	    // through the selection, so the profile is written here directly. When
401	    // the project uses this printer its copy follows the saved profile,
402	    // which would throw away edits nobody has saved yet; those are the
403	    // person's to settle first.
404	    const bool in_use = is_selected(name);
405	    if (in_use && printers.current_is_dirty())
406	        return _L("The open project has unsaved changes to this printer. Save or discard them in Printer settings, then try "
407	                  "again.");
408	
409	    // The new nozzle's profile, plus every setting the person changed on this
410	    // printer -- except the ones the two nozzle profiles themselves disagree
411	    // on, which belong to the nozzle.
412	    DynamicPrintConfig          config  = new_parent->config;
413	    const auto                  changed = PresetCollection::dirty_options(saved, old_parent);
414	    const auto                  nozzle  = PresetCollection::dirty_options(new_parent, old_parent);
415	    const std::set<std::string> nozzle_keys(nozzle.begin(), nozzle.end());
416	    for (const std::string& key : changed)
417	        if (nozzle_keys.count(key) == 0)
418	            config.set_key_value(key, saved->config.option(key)->clone());
419	    Preset::inherits(config)                                         = new_parent->name;
420	    config.option<ConfigOptionString>("printer_settings_id", true)->value = name;
421	    Preset::normalize_inherits(config, new_parent);
422	
423	    saved->base_id = new_parent->setting_id;
424	    store_unselected(*saved, std::move(config), new_parent);
425	
426	    if (in_use) {
427	        // The same printer, under the same name: only its settings moved.
428	        printers.get_edited_preset().config = saved->config;
429	        // A filament or process made for the old nozzle may not fit the new
430	        // one. The same compatibility pass Tab::select_preset runs when a
431	        // printer changes, with its default policy, re-picks whatever no
432	        // longer fits and leaves the rest alone.
433	        bundle().update_compatible(PresetSelectCompatibleType::Always, PresetSelectCompatibleType::Always);
434	        plater.update_objects_position_when_select_preset([&] { plater.on_config_change(bundle().full_config()); });
435	        printer_tab().reload_config();
436	        printer_tab().update_tab_ui();
437	        for (Preset::Type type : {Preset::TYPE_PRINT, Preset::TYPE_FILAMENT})
438	            if (Tab* tab = wxGetApp().get_tab(type))
439	                tab->load_current_preset();
440	        plater.sidebar().update_presets(Preset::TYPE_FILAMENT);
441	    }
442	    return {};
443	}
